// C2.8 open-loop load (EVAL-C28-MANIFEST section 3): k6 ramping-arrival-rate, one request per iteration, arrivals
// scheduled independently of completions. The plan (stages, VUs, seeds) is generated by the harness
// (`python -m c28 plan`), so the arrivals are a deterministic function of the block seed, the program and c.
//
//   k6 run -e C28_PLAN=plan.json -e C28_BASE_URL=http://c28-ingress.demo.svc -e C28_SUMMARY=summary.json c28.js
//
// The 2 s timeout and no retries are frozen. Dropped iterations (k6's dropped_iterations) are kept: the harness counts
// them as offered-arrival failures. For per-second mergeable latency histograms, run with the Prometheus remote-write
// output and native histograms (K6_PROMETHEUS_RW_TREND_AS_NATIVE_HISTOGRAM=true); the run-lock records the command.
import http from 'k6/http';
import { sleep } from 'k6';

const plan = JSON.parse(open(__ENV.C28_PLAN));
if (plan.schema !== 'c28-k6-plan/v1' || plan.retries !== 0) {
  throw new Error('not a c28 k6 plan');
}
const base = __ENV.C28_BASE_URL;
if (!base || !/^http:\/\//.test(base)) {
  throw new Error('C28_BASE_URL (http://...) is required');
}

export const options = {
  discardResponseBodies: true,
  scenarios: {
    c28: {
      executor: 'ramping-arrival-rate',
      startRate: plan.start_rate,
      timeUnit: plan.time_unit,
      preAllocatedVUs: plan.pre_allocated_vus,
      maxVUs: plan.max_vus,
      stages: plan.stages,
      gracefulStop: '5s',
    },
  },
  summaryTrendStats: ['avg', 'min', 'p(50)', 'p(95)', 'p(99)', 'max', 'count'],
  tags: { c28_target: plan.target, c28_seed: String(plan.seed), c28_plan: plan.digest, c28_label: plan.label },
};

// Seeded per-VU xorshift32: a small arrival jitter (0-100 ms dispatch offset) that does not change the arrival count.
let state = 0;
function rnd() {
  if (state === 0) {
    state = ((plan.jitter_seed ^ Math.imul(__VU, 2654435761)) >>> 0) || 1;
  }
  state ^= state << 13; state >>>= 0;
  state ^= state >>> 17;
  state ^= state << 5; state >>>= 0;
  return state / 4294967296;
}

export default function () {
  sleep(rnd() * 0.1);
  http.get(`${base}/t/${plan.target}/work`, { timeout: plan.timeout, tags: { name: 'work' } });
}

export function handleSummary(data) {
  const out = {};
  out[__ENV.C28_SUMMARY || 'c28-summary.json'] = JSON.stringify({ plan_digest: plan.digest, target: plan.target,
    seed: plan.seed, label: plan.label, metrics: data.metrics, state: data.state });
  return out;
}
